public class SecureUserLogin extends HttpServlet {
    public void doPost(HttpServletRequest request, HttpServletResponse response) {
        String username = request.getParameter("username");
        String password = request.getParameter("password");

        try {
            Connection conn = DriverManager.getConnection("jdbc:mysql://localhost/mydb");

            // Using PreparedStatement with parameterized queries prevents SQL injection
            // Parameters are properly escaped and treated as data, not executable code
            String query = "SELECT * FROM users WHERE username=? AND password=?";
            PreparedStatement pstmt = conn.prepareStatement(query);

            // Set parameters safely
